<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account</title><style>body{margin:0;background:#f6f7fb;font:15px system-ui;color:#111827}.box{max-width:460px;margin:8vh auto;background:#fff;padding:32px;border:1px solid #e5e7eb;border-radius:18px}.field{margin:14px 0}.field label{display:block;font-weight:700;margin-bottom:6px}.field input{width:100%;padding:12px;border:1px solid #d1d5db;border-radius:10px;box-sizing:border-box}.btn{width:100%;padding:12px;border:0;border-radius:10px;background:#111827;color:white}</style></head><body><div class="box"><h1>Create admin account</h1><form method="post" action="{{route('register.store')}}">@csrf<div class="field"><label>Name</label><input name="name" required value="{{old('name')}}"></div><div class="field"><label>Email</label><input type="email" name="email" required value="{{old('email')}}"></div><div class="field"><label>Password</label><input type="password" name="password" required></div><div class="field"><label>Confirm password</label><input type="password" name="password_confirmation" required></div><button class="btn">Create account</button></form></div></body></html>